<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header>
    <div class="brand">Support Center</div>
  </header>

  <main id="main-content">
    <section class="hero" aria-labelledby="page-title">
      <h1 id="page-title">How can we help?</h1>
      <p class="intro">
        Send a note to our support team and we will route your request to the right specialist.
      </p>
    </section>

    <section class="contact-card" aria-labelledby="form-title">
      <h2 class="form-heading" id="form-title">Contact support</h2>
      <p class="required-note"><span class="required-marker">*</span> Required fields</p>

